import { readFileSync } from "node:fs";

/**
 * Custom media (`@media (--md)`), from the breakpoint tokens. Browsers don't support
 * `@custom-media` yet, so this PostCSS plugin substitutes each `(--name)` with its query in
 * every stylesheet, after Vite has inlined the @imports. The definitions are generated by
 * scripts/build-tokens.mjs into src/styles/media.css, the single source; an unknown name
 * fails the build.
 */
const SOURCE = new URL("../src/styles/media.css", import.meta.url);
export function readCustomMedia(css: string): Map<string, string> {
  const out = new Map<string, string>();
  for (const m of css.matchAll(/@custom-media\s+(--[\w-]+)\s+([^;]+);/g)) out.set(m[1]!, m[2]!.trim());
  return out;
}

/** A media query prelude with every `(--name)` replaced. Throws on an unknown name. */
export function substituteCustomMedia(
  params: string,
  defs: Map<string, string>,
  where = "a stylesheet",
): string {
  return params.replace(/\((--[\w-]+)\)/g, (_, name: string) => {
    const q = defs.get(name);
    if (!q) throw new Error(`custom-media: unknown ${name} in ${where} (see src/styles/media.css)`);
    return q;
  });
}

interface MediaRule {
  params: string;
  source?: { input: { file?: string } } | undefined;
}

/** The PostCSS plugin (typed structurally, so this file needs no postcss import). */
export function customMedia() {
  let defs: Map<string, string> | null = null;
  return {
    postcssPlugin: "custom-media",
    AtRule: {
      media(rule: MediaRule): void {
        if (!rule.params.includes("(--")) return;
        defs ??= readCustomMedia(readFileSync(SOURCE, "utf8"));
        rule.params = substituteCustomMedia(rule.params, defs, rule.source?.input.file);
      },
    },
  };
}
